INSERT INTO src VALUES
  ('The Irrawaddy', 'https://www.irrawaddy.com', 'https://www.irrawaddy.com/feed', 'irrawaddy.com', 'rss, 10 items, newest 2026-10-16', $$Média privé indépendant (Irrawaddy Publishing Group)$$, $$Irrawaddy Publishing Group ; fondé et dirigé par Aung Zaw$$, $$Fondé en 1990 à Bangkok par Aung Zaw, ancien militant étudiant de l'université de Rangoun exilé après la répression de 1988 ; installé à Chiang Mai, puis rédaction à Rangoun après les réformes de 2012. Soutenu à l'origine par des donateurs internationaux (National Endowment for Democracy, Open Society Foundations).$$, $$Licence révoquée par la junte en octobre 2022 ; continue de publier en anglais et en birman depuis l'exil. Média indépendant, critique du régime militaire.$$, $$Fondation, financement et interdiction documentés par Wikipédia (sources de presse citées).$$, $$[{"url": "https://en.wikipedia.org/wiki/The_Irrawaddy", "note": "Fondé en 1990 par Aung Zaw ; Irrawaddy Publishing Group ; donateurs NED et OSF ; licence révoquée en octobre 2022", "category": "reference", "accessed_at": "2026-10-19"}]$$::jsonb),
  ('Myanmar Now', 'https://myanmar-now.org/en', 'https://myanmar-now.org/en/feed/', 'myanmar-now.org', 'rss, 10 items, newest 2026-10-16', $$Agence de presse indépendante$$, $$Rédaction indépendante dirigée par Swe Win (rédacteur en chef)$$, $$Agence de presse fondée en août 2015 avec le soutien de la Thomson Reuters Foundation ; contenus diffusés gratuitement à plus de 50 médias.$$, $$Locaux perquisitionnés par l'armée le 8 mars 2021 et licence révoquée par la junte ; poursuit un journalisme d'investigation indépendant, primé en 2023.$$, $$Fondation, direction et interdiction documentées par Wikipédia (sources de presse citées).$$, $$[{"url": "https://en.wikipedia.org/wiki/Myanmar_Now", "note": "Fondé en 2015 avec la Thomson Reuters Foundation ; rédacteur en chef Swe Win ; perquisition et licence révoquée en mars 2021", "category": "reference", "accessed_at": "2026-10-19"}]$$::jsonb),
  ('DVB English', 'https://english.dvb.no', 'https://english.dvb.no/feed/', 'english.dvb.no', 'rss, 10 items, newest 2026-10-19', $$Organisation de médias à but non lucratif$$, $$DVB Multimedia Group (Democratic Voice of Burma) ; directeur exécutif et rédacteur en chef Aye Chan Naing$$, $$Democratic Voice of Burma, fondée en juillet 1992 à Oslo et Chiang Mai par des expatriés birmans pour diffuser une information non censurée ; télévision lancée en 2005 avec l'aide d'ONG (Free Voice, National Endowment for Democracy, Freedom of Expression Foundation).$$, $$Interdite par la junte le 8 mars 2021 avec quatre autres médias, licences révoquées ; opère de nouveau dans la clandestinité et depuis l'étranger. Service en anglais sur english.dvb.no.$$, $$Fondation, structure et interdiction documentées par Wikipédia (sources citées).$$, $$[{"url": "https://en.wikipedia.org/wiki/Democratic_Voice_of_Burma", "note": "Fondée en 1992 (Oslo, Chiang Mai) ; organisation à but non lucratif DVB Multimedia Group ; interdite le 8 mars 2021", "category": "reference", "accessed_at": "2026-10-19"}]$$::jsonb);
DO $$
DECLARE mm int; bad int; n int; s record; sid int; pid int;
BEGIN
  -- 1. dormant publishers off
  UPDATE publishers SET feed_status = 'unavailable' WHERE id IN (992,200,308) AND feed_status = 'active';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 3 THEN RAISE EXCEPTION 'dormant: % set unavailable, expected 3', n; END IF;
  UPDATE feeds SET enabled = false WHERE publisher_id IN (992,200,308) AND enabled;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 3 THEN RAISE EXCEPTION 'dormant: % feeds disabled, expected 3', n; END IF;

  -- 2. Myanmar sources (same refusal as findPublisherConflict, plus an earlier run of this script)
  SELECT id INTO mm FROM countries WHERE iso_code = 'MM';
  IF mm IS NULL THEN RAISE EXCEPTION 'no MM country'; END IF;
  SELECT count(*) INTO bad FROM src x
   WHERE EXISTS (SELECT 1 FROM publishers p WHERE p.country_id = mm AND (lower(p.name) = lower(x.name)
                 OR lower(regexp_replace(regexp_replace(p.domain, '^www[.]', ''), '/+$', '')) = x.domain))
      OR EXISTS (SELECT 1 FROM feeds f WHERE f.feed_url = x.feed)
      OR EXISTS (SELECT 1 FROM publisher_submissions ps WHERE ps.verification_detail LIKE '%' || '[added by Claude 2026-10-19, Build #96 Myanmar sources]');
  IF bad > 0 THEN RAISE EXCEPTION '% of 3 already exist as a publisher, feed or earlier run - nothing changed', bad; END IF;
  n := 0;
  FOR s IN SELECT * FROM src ORDER BY name LOOP
    INSERT INTO publisher_submissions (name, homepage_url, feed_url, feed_type, country_id, language, feed_verified,
      verification_detail, domain, ingestion_method, status, status_changed_at, reviewed_at)
    VALUES (s.name, s.homepage, s.feed, 'rss', mm, 'en', true,
      'Feed checked 2026-10-19: ' || s.note || ' ' || '[added by Claude 2026-10-19, Build #96 Myanmar sources]', s.domain, 'feed', 'approved', now(), now())
    RETURNING id INTO sid;
    INSERT INTO publishers (country_id, name, homepage_url, feed_status, language, domain, source_type)
    VALUES (mm, s.name, s.homepage, 'active', 'en', s.domain, 'ONLINE_NEWS') RETURNING id INTO pid;
    INSERT INTO feeds (publisher_id, feed_url, feed_type) VALUES (pid, s.feed, 'rss');
    UPDATE publisher_submissions SET publisher_id = pid WHERE id = sid;
    INSERT INTO editorial_profiles (publisher_id, ownership_type, owner, classification_tags, political_party_association, historical_context,
      current_context, confidence, evidence_summary, evidence_sources, classification_date, last_reviewed, evidence_date, review_required)
    VALUES (pid, s.ownership_type, s.owner, ARRAY['independent']::text[], NULL, s.historical_context, s.current_context, 'high',
      s.evidence_summary, s.evidence_sources, DATE '2026-10-19', DATE '2026-10-19', DATE '2026-10-19', false);
    n := n + 1;
  END LOOP;
  IF n <> 3 THEN RAISE EXCEPTION 'added %, expected 3', n; END IF;
END $$;
SELECT 'added|' || p.id || '|' || p.name || '|' || p.feed_status || '|' || f.feed_url || '|profile ' || array_to_string(e.classification_tags, ',')
  FROM publisher_submissions s JOIN publishers p ON p.id = s.publisher_id JOIN feeds f ON f.publisher_id = p.id
  JOIN editorial_profiles e ON e.publisher_id = p.id WHERE s.verification_detail LIKE '%' || '[added by Claude 2026-10-19, Build #96 Myanmar sources]' ORDER BY p.id;
SELECT 'dormant|' || p.id || '|' || p.name || '|' || p.feed_status || '|enabled ' || bool_or(f.enabled)
  FROM publishers p JOIN feeds f ON f.publisher_id = p.id WHERE p.id IN (992,200,308) GROUP BY p.id, p.name, p.feed_status ORDER BY 1;
SELECT 'coverage|' || c.iso_code || '|' || count(*) FILTER (WHERE p.feed_status = 'active') || ' active'
  FROM countries c JOIN publishers p ON p.country_id = c.id WHERE c.iso_code IN ('MM','TG','KM') GROUP BY c.iso_code ORDER BY 1;
SELECT 'gap|' || count(*) || ' active publishers without a profile'
  FROM publishers p LEFT JOIN editorial_profiles e ON e.publisher_id = p.id WHERE p.feed_status = 'active' AND e.id IS NULL;
COMMIT;
